    $read=fn(string $id)=>$db->query('SELECT * FROM DatBan WHERE maDatBan='.$db->quote($id))->fetch();
    run_case('DB01','Đặt bàn','Gửi hợp lệ','CN01; 4 khách; thời gian tương lai','Lưu CHO_XAC_NHAN, maBan NULL; không đổi trạng thái bàn',function()use($create,$db){$d=$create();check($d['trangThai']==='CHO_XAC_NHAN'&&$d['maBan']===null);check((int)$db->query("SELECT COUNT(*) FROM Ban WHERE trangThai<>'TRONG'")->fetchColumn()===0);});
    run_case('DB02','Đặt bàn','Thiếu họ tên','tenKhach rỗng','VALIDATION_ERROR; không lưu',fn()=>fails('VALIDATION_ERROR',fn()=>$create(['tenKhach'=>''])));
    run_case('DB03','Đặt bàn','Sai số điện thoại','SĐT abc','VALIDATION_ERROR',fn()=>fails('VALIDATION_ERROR',fn()=>$create(['soDienThoai'=>'abc'])));
    run_case('DB04','Đặt bàn','Số khách không nguyên dương','0; -1; 1.5; mảng','Tất cả bị từ chối',function()use($create){foreach(['0','-1','1.5',[]]as $q)fails('VALIDATION_ERROR',fn()=>$create(['soKhach'=>$q]));});
    run_case('DB05','Đặt bàn','Ngày giờ quá khứ hoặc không tồn tại','Ngày hôm qua; 2026-02-30','VALIDATION_ERROR',function()use($create){fails('VALIDATION_ERROR',fn()=>$create(['thoiGianDen'=>'2020-01-01T18:00']));fails('VALIDATION_ERROR',fn()=>$create(['thoiGianDen'=>'2030-02-30T18:00']));});
    run_case('DB06','Đặt bàn','Chi nhánh ngừng hoạt động','CN01 NGUNG','VALIDATION_ERROR; không lưu',function()use($create,$db){$db->exec("UPDATE ChiNhanh SET trangThai='NGUNG' WHERE maChiNhanh='CN01'");fails('VALIDATION_ERROR',$create);check((int)$db->query('SELECT COUNT(*) FROM DatBan')->fetchColumn()===0);});
    run_case('DB07','Đặt bàn','Giới hạn độ dài và kiểu dữ liệu','Tên 101 ký tự; chi nhánh dạng mảng','VALIDATION_ERROR',function()use($create){fails('VALIDATION_ERROR',fn()=>$create(['tenKhach'=>str_repeat('a',101)]));fails('VALIDATION_ERROR',fn()=>$create(['maChiNhanh'=>[]]));});
    run_case('DB08','Đặt bàn','Chuỗi SQL được lưu như dữ liệu',"Tên O'Neil; DROP TABLE DatBan; --",'Tên lưu nguyên văn; bảng DatBan còn nguyên',function()use($create,$db){$text="O'Neil; DROP TABLE DatBan; --";$d=$create(['tenKhach'=>$text]);check($d['tenKhach']===$text);check((int)$db->query('SELECT COUNT(*) FROM DatBan')->fetchColumn()===1);});
    run_case('TD01','Theo dõi trạng thái','Tra cứu số điện thoại đã đặt','0912345678','Trả đúng yêu cầu và chi nhánh',function()use($create,$control){$d=$create();$r=$control->theoDoiTrangThai('0912345678');check(count($r)===1&&$r[0]['maDatBan']===$d['maDatBan']);check(isset($r[0]['tenChiNhanh']));});
    run_case('TD02','Theo dõi trạng thái','Số không có yêu cầu','0999999999','Kết quả rỗng',fn()=>check($control->theoDoiTrangThai('0999999999')===[]));
    run_case('TD03','Theo dõi trạng thái','Số không hợp lệ','chuỗi SQL hoặc rỗng','VALIDATION_ERROR',function()use($control){foreach(['',"' OR 1=1 --"]as $p)fails('VALIDATION_ERROR',fn()=>$control->theoDoiTrangThai($p));});
