    run_case('TC04','Tra cứu đặt bàn','Khách/Bếp không có quyền','actor NULL hoặc BEP','FORBIDDEN',function()use($control,$kitchen){fails('FORBIDDEN',fn()=>$control->traCuuDatBan(null));fails('FORBIDDEN',fn()=>$control->traCuuDatBan($kitchen));});
    run_case('TC05','Tra cứu đặt bàn','Lọc ngày và trạng thái','Ngày đúng/sai; trạng thái hợp lệ/không hợp lệ','Lọc đúng; bộ lọc không hợp lệ bị từ chối',function()use($create,$control,$waiter,$start){$create();check(count($control->traCuuDatBan($waiter,'',substr($start,0,10),'CHO_XAC_NHAN'))===1);check($control->traCuuDatBan($waiter,'','2020-01-01')===[]);fails('VALIDATION_ERROR',fn()=>$control->traCuuDatBan($waiter,'','2030-02-30'));fails('VALIDATION_ERROR',fn()=>$control->traCuuDatBan($waiter,'','','BAD'));});
    run_case('TC06','Tra cứu đặt bàn','Ký tự LIKE và SQL không mở rộng truy vấn','%; _; chuỗi SQL','Chỉ tìm chuỗi literal; không trả toàn bộ',function()use($create,$control,$waiter){$create();foreach(['%','_',"' OR 1=1 --"]as $t)check($control->traCuuDatBan($waiter,$t)===[]);});
    run_case('XN01','Xác nhận đặt bàn','Xác nhận bàn phù hợp','CN01, bàn 4 ghế; khung giờ hợp lệ','Gán bàn, DA_XAC_NHAN, người xác nhận; trạng thái vật lý vẫn TRONG',function()use($create,$control,$waiter,$end,$db){$d=$create();check(count($control->kiemTraBanPhuHop($waiter,$d['maDatBan'],$end))>0);$r=$control->xacNhanDatBan($waiter,$d['maDatBan'],'C1-A01',$end);check($r['trangThai']==='DA_XAC_NHAN'&&$r['maBan']==='C1-A01'&&$r['maNguoiXacNhan']==='TSWAIT1');check($db->query("SELECT trangThai FROM Ban WHERE maBan='C1-A01'")->fetchColumn()==='TRONG');});
    run_case('XN02','Xác nhận đặt bàn','Bàn thiếu sức chứa hoặc ngừng','4 khách; bàn 2 ghế / NGUNG','CONFLICT; đơn vẫn chờ',function()use($create,$control,$waiter,$end,$read,$db){$d=$create();fails('CONFLICT',fn()=>$control->xacNhanDatBan($waiter,$d['maDatBan'],'C1-A02',$end));$db->exec("UPDATE Ban SET trangThai='NGUNG' WHERE maBan='C1-A01'");fails('CONFLICT',fn()=>$control->xacNhanDatBan($waiter,$d['maDatBan'],'C1-A01',$end));check($read($d['maDatBan'])['maBan']===null);});
    run_case('XN03','Xác nhận đặt bàn','Bàn sai chi nhánh và actor sai phạm vi','Bàn CN02 hoặc phục vụ CN02','VALIDATION_ERROR/FORBIDDEN',function()use($create,$control,$waiter,$other,$end){$d=$create();fails('VALIDATION_ERROR',fn()=>$control->xacNhanDatBan($waiter,$d['maDatBan'],'C2-A01',$end));fails('FORBIDDEN',fn()=>$control->xacNhanDatBan($other,$d['maDatBan'],'C2-A01',$end));});
    run_case('XN04','Xác nhận đặt bàn','Khung giờ trùng','Hai yêu cầu cùng bàn và khoảng','Yêu cầu sau CONFLICT, còn chờ',function()use($create,$control,$waiter,$end,$read){$a=$create();$b=$create();$control->xacNhanDatBan($waiter,$a['maDatBan'],'C1-A01',$end);fails('CONFLICT',fn()=>$control->xacNhanDatBan($waiter,$b['maDatBan'],'C1-A01',$end));check($read($b['maDatBan'])['trangThai']==='CHO_XAC_NHAN');});
    run_case('XN05','Xác nhận đặt bàn','Hai khoảng sát giờ','18–20 và 20–22 cùng bàn','Cả hai được xác nhận theo khoảng [đầu, cuối)',function()use($create,$control,$waiter,$end){$a=$create();$control->xacNhanDatBan($waiter,$a['maDatBan'],'C1-A01',$end);$b=$create(['thoiGianDen'=>$end]);$r=$control->xacNhanDatBan($waiter,$b['maDatBan'],'C1-A01',(new DateTimeImmutable('tomorrow 22:00'))->format('Y-m-d\TH:i'));check($r['trangThai']==='DA_XAC_NHAN');});
