    run_case('XN07','Xác nhận đặt bàn','Không có bàn phù hợp','32767 khách','Danh sách bàn rỗng',function()use($create,$control,$waiter,$end){$d=$create(['soKhach'=>'32767']);check($control->kiemTraBanPhuHop($waiter,$d['maDatBan'],$end)===[]);});
    run_case('TQ01','Tạo đặt bàn tại quầy','Tiếp nhận hợp lệ','Bàn trống 4 ghế; 4 khách','Đơn và bàn DANG_PHUC_VU; lưu giờ nhận',function()use($control,$waiter,$counter,$db){$d=$control->taoDonTaiQuay($waiter,$counter);check($d['trangThai']==='DANG_PHUC_VU'&&$d['thoiGianNhanBan']!==null&&$d['nguon']==='TAI_QUAY');check($db->query("SELECT trangThai FROM Ban WHERE maBan='C1-A01'")->fetchColumn()==='DANG_PHUC_VU');});
