    run_case('TQ03','Tạo đặt bàn tại quầy','Xung đột với lịch xác nhận','Lịch giữ trong 30–90 phút tới; khách quầy phục vụ 2 giờ','CONFLICT; không đổi bàn',function()use($create,$control,$waiter,$counter,$db){$a=$create(['thoiGianDen'=>(new DateTimeImmutable('+30 minutes'))->format('Y-m-d\TH:i')]);$control->xacNhanDatBan($waiter,$a['maDatBan'],'C1-A01',(new DateTimeImmutable('+90 minutes'))->format('Y-m-d\TH:i'));fails('CONFLICT',fn()=>$control->taoDonTaiQuay($waiter,$counter));check($db->query("SELECT trangThai FROM Ban WHERE maBan='C1-A01'")->fetchColumn()==='TRONG');});
    run_case('TQ04','Tạo đặt bàn tại quầy','Tên/SĐT tùy chọn nhưng nhập phải hợp lệ','Bỏ trống; SĐT abc','Bỏ trống được lưu NULL; SĐT sai bị từ chối',function()use($control,$waiter,$counter){fails('VALIDATION_ERROR',fn()=>$control->taoDonTaiQuay($waiter,array_replace($counter,['soDienThoai'=>'abc'])));$d=$control->taoDonTaiQuay($waiter,$counter);check($d['tenKhach']===null&&$d['soDienThoai']===null);});
