    run_case('TQ06','Tạo đặt bàn tại quầy','Kết thúc đã qua','Giờ kết thúc hôm qua','VALIDATION_ERROR',fn()=>fails('VALIDATION_ERROR',fn()=>$control->taoDonTaiQuay($waiter,array_replace($counter,['thoiGianKetThucDuKien'=>'2020-01-01T18:00']))));
    run_case('TQ07','Tạo đặt bàn tại quầy','Rollback khi lỗi cập nhật bàn','Trigger kiểm thử gây lỗi UPDATE Ban','Không còn đơn mới; bàn vẫn TRONG',function()use($control,$waiter,$counter,$db){$db->exec("CREATE TRIGGER test_booking_fail BEFORE UPDATE ON Ban FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Injected test failure'");try{$failed=false;try{$control->taoDonTaiQuay($waiter,$counter);}catch(PDOException){$failed=true;}check($failed);check((int)$db->query('SELECT COUNT(*) FROM DatBan')->fetchColumn()===0);check($db->query("SELECT trangThai FROM Ban WHERE maBan='C1-A01'")->fetchColumn()==='TRONG');}finally{$db->exec('DROP TRIGGER test_booking_fail');}});
