    run_case('XN08','Xác nhận đặt bàn','Hai nhân viên tranh cùng bàn','Hai process, hai yêu cầu, cùng bàn/khung giờ','Đúng 1 thành công, 1 CONFLICT; không đặt trùng',function()use($create,$name,$end,$db,$root){
        $a=$create();$b=$create();$jobs=[];
        foreach([$a,$b]as $d){$pipes=[];$p=proc_open([PHP_BINARY,$root.'/tests/dat-ban/worker.php',$name,'confirm',$d['maDatBan'],$end],[1=>['pipe','w'],2=>['pipe','w']],$pipes);check(is_resource($p));$jobs[]=[$p,$pipes];}
        $codes=[];foreach($jobs as [$process,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);check(proc_close($process)===0,$err);$r=json_decode($out,true,512,JSON_THROW_ON_ERROR);$codes[]=$r['code'];}
        sort($codes);check($codes===['CONFLICT','OK'],json_encode($codes));check((int)$db->query("SELECT COUNT(*) FROM DatBan WHERE trangThai='DA_XAC_NHAN'")->fetchColumn()===1);
    });
    run_case('TQ08','Tạo đặt bàn tại quầy','Hai process tiếp nhận cùng bàn','Hai request quầy đồng thời','Đúng 1 thành công và 1 CONFLICT',function()use($name,$counter,$root,$db){$jobs=[];foreach([1,2]as $i){$pipes=[];$p=proc_open([PHP_BINARY,$root.'/tests/dat-ban/worker.php',$name,'counter','unused',$counter['thoiGianKetThucDuKien']],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$jobs[]=[$p,$pipes];}$codes=[];foreach($jobs as [$process,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);check(proc_close($process)===0,$err);$codes[]=json_decode($out,true,512,JSON_THROW_ON_ERROR)['code'];}sort($codes);check($codes===['CONFLICT','OK'],json_encode($codes));check((int)$db->query('SELECT COUNT(*) FROM DatBan')->fetchColumn()===1);});
} finally {
    if($db->inTransaction())$db->rollBack();
    if($created)$db->exec("DROP DATABASE `$name`");
}
$out=getenv('RESERVATION_TEST_RESULTS')?:__DIR__.'/results.json';file_put_contents($out,json_encode(['executed_at'=>date(DATE_ATOM),'database_isolated'=>true,'total'=>count($results),'passed'=>count(array_filter($results,fn($r)=>$r['status']==='PASS')),'cases'=>$results],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));
exit(count(array_filter($results,fn($r)=>$r['status']==='FAIL'))?1:0);
